B.ePF=new A.y("recencyColumns",B.a7,'Ordered timestamp columns checked to find the Now lane\'s "in motion" row per project group (default [postedAt, editedAt]).',B.j,null,!1)
B.eRP=new A.y("orderColumn",B.H,"Numeric tiebreak column for the in-motion pick (default order).",B.j,null,!1)
