B.eQ1=new A.y("routingToProperty",B.T,'GeoJSON feature property read as an edge\'s "to" node id (default "to").',B.j,null,!1)
B.eF0=new A.y("routingSpeedKmh",B.aG,"Network speed (km/h) used to derive an edge's travel time from its geometry length when the edge has no explicit weight (default 33.0 \u2014 match a bake's own model speed for consistent estimates).",B.j,null,!1)
B.eQX=new A.y("routingDwellMin",B.aG,"Per-edge dwell time (minutes) added to every derived edge weight (default 0.5).",B.j,null,!1)
B.eJv=new A.y("snapMaxKm",B.aG,'Max straight-line distance (km) a pin may snap to the nearest routing node (default 1.5). Beyond this, that leg reports an honest "no nearby station" state instead of a fabricated route.',B.j,null,!1)
B.eZr=new A.y("routeColor",B.T,"Highlighted route-overlay polyline color (default: theme error color) \u2014 visually distinct from any static line sourceLayers.",B.j,null,!1)
B.eSK=new A.y("routeWidth",B.aG,"Route-overlay polyline stroke width (default 4).",B.j,null,!1)
B.eRB=new A.y("allowRotate",B.a8,"Let the user rotate the map camera (two-finger twist). Default off (north-locked) \u2014 an applet opts a specific map into rotation.",B.j,null,!1)
B.ePz=new A.y("allowTilt",B.a8,"Let the user tilt the map camera (two-finger drag). Default off (flat, no pitch) \u2014 an applet opts a specific map into tilt.",B.j,null,!1)
