B.enE=new A.dm("sidescroller","A real-time side-scrolling platformer with its own game loop (joystick + jump/attack); optional high-score persistence.",B.cUx,!1)
B.eDJ=new A.y("cols",B.aG,"Grid columns (default 36).",B.j,null,!1)
