B.aK4=new A.y("rowId",B.T,"Row to edit; usually injected by a pages/explorer detail.",B.j,null,!1)
B.eQY=new A.y("column",B.H,'Column storing the document Delta JSON (default "body").',B.j,null,!1)
B.eJ5=new A.y("page",B.a8,'Page-look surface \u2014 a centered max-width "paper". On by default; set false for a plain full-bleed editor.',B.j,null,!1)
B.f_p=new A.y("fonts",B.a7,'Override the font-family picker: {"Label": "Family", \u2026}. Omit to use the bundled document fonts (Lora, Inter, Space Grotesk, IM Fell English, Special Elite, Rye).',B.j,null,!1)
B.eZW=new A.y("title",B.T,'Document title used when printing (default "Document"); may be a {lang: text} map.',B.j,null,!0)
